import{initializeApp}from"https://www.gstatic.com/firebasejs/10.11.1/firebase-app.js";import{getFirestore,collection,addDoc,serverTimestamp}from"https://www.gstatic.com/firebasejs/10.11.1/firebase-firestore.js";const firebaseConfig={apiKey:"AIzaSyCLC4Dz-qxNOPtRFhybiBA5SqCDJgvKqMY",authDomain:"neat-53fa9.firebaseapp.com",projectId:"neat-53fa9",storageBucket:"neat-53fa9.appspot.com",messagingSenderId:"857317417173",appId:"1:857317417173:web:6b84a45c96ebe56fce425c"},app=initializeApp(firebaseConfig),db=getFirestore(app),form=document.querySelector("#subscribeForm"),emailInput=document.querySelector("#email"),alertBox=document.querySelector("#customAlert");function showAlert(e,t=2500){alertBox&&(alertBox.textContent=e,alertBox.classList.add("show"),setTimeout((()=>alertBox.classList.remove("show")),t))}async function saveEmailToFirestore(e){await addDoc(collection(db,"email"),{email:e,timestamp:serverTimestamp()})}form.addEventListener("submit",(async e=>{e.preventDefault();const t=emailInput.value.trim();if(t)try{showAlert("Please wait, saving your details..."),await saveEmailToFirestore(t),showAlert("✨ Email saved – welcome to the Neat Family!",3500)}catch(e){console.error("Firestore error →",e),alert("Sorry — couldn’t save your email. Please try again.")}else alert("Please enter a valid email address.")}));